{

"kind": "propose",
"summary": "Adjust liveness probe timeout due to startup delays",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Pod failed liveness probe during startup with timeout 1s, but logs show it took 1m2s to start",
    "supporting": ["ev-container_logs_tail", "ev-target_events", "ev-pod_states"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_broken",
    "summary": "Failure started after rollout to revision 4 with image change, but logs show app starts normally",
    "supporting": ["ev-rollout_history", "ev-pod_states"],
    "contradicting": ["ev-container_logs_tail"],
    "missing": ["memory_data_available"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Allow 10s for app to start before liveness probe timeout",
  "rationale": "Logs show app took 1m2s to start but probe timeout is 1s. Increasing timeout to 10s matches initialDelaySeconds and allows startup completion.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-target_events", "ev-pod_states", "ev-rollout_history"],
  "cited_predicates": ["failure_onset_after_rollout", "rollout_changed_the_app", "killed_during_startup"]
}
}
